use iced::widget::svg;
use iced::{Color, Length};

pub fn icon<'a>(bytes: &'static [u8], size: f32, color: Color) -> svg::Svg<'a> {
    svg(svg::Handle::from_memory(bytes))
        .width(Length::Fixed(size))
        .height(Length::Fixed(size))
        .style(move |_theme, _status| svg::Style { color: Some(color) })
}

pub fn brand_mark<'a>(size: f32, dark: bool) -> svg::Svg<'a> {
    let bytes: &'static [u8] = if dark {
        BRAND_MARK_DARK
    } else {
        BRAND_MARK_LIGHT
    };
    svg(svg::Handle::from_memory(bytes))
        .width(Length::Fixed(size))
        .height(Length::Fixed(size))
}

pub fn brand_mark_on_accent<'a>(size: f32) -> svg::Svg<'a> {
    svg(svg::Handle::from_memory(BRAND_MARK_ON_ACCENT))
        .width(Length::Fixed(size))
        .height(Length::Fixed(size))
}

